const SKIN=['#b57a52','#8a5a3a','#d9a07a','#6a4430'];

/* ============ ESTADO ============ */
function newF(i,ch){return {i,ch,x:i?340:140,y:0,vx:0,vy:0,kv:0,face:i?-1:1,hp:MAXHP,en:START_EN,st:'idle',walk:0,atk:null,cast:null,leap:null,cd:0,stun:0,slow:0,burn:0,burnDps:0,burnAcc:0,burnCol:'#ff7a1a',burnBy:0,inv:0,sa:0,spk:0,spkAcc:0,spkBy:0,hits:0,stacks:0,stackT:0,thin:0,cl:0,rage:0,away:false,awayDir:1,tf:0,blk:false,cr:false,rc:false,flash:0,ko:false,kt:0,hv:0,win:false,wp:0,ta:{l:0,h:0},pose:'',secOn:false,secSeen:false,js:0,jsT:0}}
function newGame(chars,stage,o){
 const G={chars:chars.slice(),p:[newF(0,chars[0]),newF(1,chars[1])],proj:[],fx:[],hf:[],txt:[],banner:null,phase:'intro',pt:0,round:1,wins:[0,0],timer:ROUND_TIME,shake:0,dim:0,ev:[],evn:0,winner:-2,rw:-1,f2:false,tick:0,stage:stage|0};
 G.banner={txt:'ROUND 1',sub:'',col:'#ffd84a',t:0,dur:1.1};
 if(o&&o.one){G.one=true;G.nm=o.nm||['',''];G.al=o.al||[3,3];G.banner={txt:o.bn||'LUTA!',sub:'',col:'#ffd84a',t:0,dur:1.1};for(let i=0;i<2;i++){if(o.hp)G.p[i].hp=o.hp[i];if(o.en)G.p[i].en=o.en[i]}}
 return G;
}
function resetRound(G){
 G.p=[newF(0,G.chars[0]),newF(1,G.chars[1])];G.proj=[];G.fx=[];G.hf=[];G.timer=ROUND_TIME;G.phase='intro';G.pt=0;G.f2=false;G.dim=0;G.rw=-1;
 G.banner={txt:'ROUND '+G.round,sub:'',col:'#ffd84a',t:0,dur:1.1};
}
const ev=(G,n)=>{G.evn++;G.ev.push([G.evn,n]);if(G.ev.length>14)G.ev.shift()};
const txt=(G,x,y,s,col)=>G.txt.push({x,y,s,age:0,col:col||'#fff'});
const hfx=(G,x,y,col,big)=>G.hf.push({x,y,age:0,col,big:big||0});
const fmt=d=>d>=10?String(Math.round(d)):(Math.round(d*10)/10).toFixed(1);

/* ============ DANO ============ */
function basicDmg(p,e,k){
 const c=CH[p.ch];let d=(c.fix!=null?c.fix:c.bp/100*CH[e.ch].spec)*BASIC_SCALE;
 if(p.ch==='jorge'){if(p.js>0)d*=1+.05*p.js;if(p.fire)d*=2}
 if(p.ch==='hered'&&e.wet>0)d+=0.04*CH[e.ch].spec*BASIC_SCALE;
 if(k==='h')d*=HEAVY_MULT;
 if(p.ch==='kabo'&&p.thin>0)d=.15*e.hp;
 return Math.max(.8,d);
}
function burn(T,by,dps,dur,col){T.burn=dur;T.burnDps=dps;T.burnCol=col;T.burnBy=by;T.burnAcc=0}
const SUB_SK2={name:'ATESTADO SEGUNDA-FEIRA',cd:8,close:null,wind:.3,rec:.4,run:'submao2',skill:1};
function lock(V,t,pose){if(V.sa>0)return;V.stun=Math.max(V.stun,t);V.atk=null;V.leap=null;V.dash=null;if(V.cast&&V.cast.d.skill&&!V.cast.fired)V.cast=null;if(pose)V.pose=pose}
function dealHit(G,a,v,dmg,o){
 const A=G.p[a],V=G.p[v];
 if(A.ch==='dpaul'&&A.stacks>0)dmg*=1+Math.min(.15,.0375*A.stacks);
 if(G.phase!=='fight'||V.ko||V.away)return false;
 const kind=o.kind;let blocked=false;
 if((kind==='basic'||kind==='proj')&&V.blk){
  if(CH[A.ch].gb&&kind==='basic'){V.blk=false;V.stun=Math.max(V.stun,.55);ev(G,'break');txt(G,V.x,V.y+70,'ESCUDO RASGADO','#ff9a5a')}
  else if(V.ch==='kbene'&&V.cl<=0){V.cl=5;ev(G,'block');G.fx.push({t:'cloneabs',v,age:0,dur:.45});txt(G,V.x,V.y+70,'CLONE!','#9ad');return true}
  else blocked=true;
 }
 if(blocked){
  dmg*=BLOCK_MULT;ev(G,'block');
  if(kind==='basic'){
   if(V.ch==='dpaul')dealHit(G,v,a,1.5,{kind:'dot'});
   if(V.ch==='moraes')burn(A,v,2*K,2,'#ff7a1a');
   if(V.ch==='kabo')dealHit(G,v,a,1,{kind:'dot'});
  }
 }
 if(V.rage>0)dmg*=1.25;
 if(V.ch==='reymond'&&V.tf>0)dmg*=.7;
 V.hp=Math.max(V.inv>0?1:0,V.hp-dmg);V.flash=.14;
 if(!blocked&&kind!=='dot'&&A.ch!=='kbene'&&!A.ko){const hl=(A.ch==='jorge'&&kind==='basic'?.07:LIFESTEAL)*MAXHP;A.hp=Math.min(MAXHP,A.hp+hl);txt(G,A.x,A.y+76,'+'+Math.round(hl),'#6bff9a')}
 txt(G,V.x+rnd(-6,6),V.y+66,fmt(dmg),blocked?'#9ad':(kind==='special'||kind==='skill')?'#ffd84a':'#fff');
 if(kind!=='dot'&&kind!=='special'){A.en=Math.min(100,A.en+7);V.en=Math.min(100,V.en+5)}
 if(!blocked&&!(V.sa>0)){
  if(o.stun)lock(V,o.stun);
  else if(kind==='basic'||kind==='proj'){lock(V,o.k==='h'?.3:.14);V.kv=A.face*(o.k==='h'?240:130)}
  if(o.kb)V.kv=A.face*o.kb;
  V.hv=((V.hv|0)+1)%6;
 }
 G.shake=Math.max(G.shake,kind==='special'?10:kind==='skill'?6:o.k==='h'?4:kind==='dot'?0:2);
 if(kind!=='dot'&&!(G.hs>0)&&!(G.hsc>0)){G.hs=blocked?.03:(kind==='special'||kind==='skill')?.09:o.k==='h'?.07:.045;G.hsc=.22}
 if(kind!=='dot'){if(!blocked)ev(G,'punch');hfx(G,V.x,V.y+34,A.ch==='moraes'?'#ff8a2a':A.ch==='kabo'?'#ff7ac8':'#fff',kind==='special'||kind==='skill'?1:0)}
 if(kind==='basic'&&!blocked)onHit(G,A,V);
 if(V.hp<=0)koF(G,v,a);
 return true;
}
function onHit(G,A,V){
 A.hits++;
 if(A.ch==='jorge'){A.fire=(A.hits%4===0);if(A.js>0)A.jsT=10;if(A.fire){A.js=Math.min(3,A.js+1);A.jsT=10;txt(G,A.x,A.y+78,'FOGO ROXO','#c58aff')}}
 if(A.ch==='berri'){V.spk=1.2;V.spkBy=A.i;if(!(V.spkAcc>0))V.spkAcc=0}
 if(A.ch==='hered'&&A.hits%2===0){V.wet=6;txt(G,V.x,V.y+78,'MOLHADO','#ffd35a')}
 if(A.ch==='vald'&&A.hits%2===0){V.paint=8;A.marks=(A.marks||0)+1;txt(G,V.x,V.y+78,'MARCADO','#ffe21a');if(A.marks>=3){A.marks=0;A.rng=7;txt(G,A.x,A.y+86,'À DISTÂNCIA!','#9ad8ff')}}
 if(A.ch==='dpaul'&&A.hits%3===0){A.stacks=Math.min(4,A.stacks+1);A.stackT=10;txt(G,A.x,A.y+72,'INCHOU!','#ffb27a')}
 if(A.ch==='moraes'&&A.hits%3===0){burn(V,A.i,2*K,3,'#ff7a1a');txt(G,V.x,V.y+78,'QUEIMOU','#ff9a5a')}
 if(A.ch==='kabo'&&A.hits%4===0){burn(V,A.i,1*K,3,'#ff6fc8');txt(G,V.x,V.y+78,'ROSAS','#ff9ad8')}
 if(A.ch==='kbene'&&A.hits%10===0){A.hp=Math.min(MAXHP,A.hp+1*K);txt(G,A.x,A.y+72,'+'+(1*K),'#6bff9a')}
}
function koF(G,v,a){
 const V=G.p[v];V.ko=true;V.vy=220;V.kv=-G.p[a].face*140;V.cast=null;V.atk=null;V.leap=null;V.stun=0;V.burn=0;V.pose='';V.blk=false;
 G.phase='ko';G.pt=0;G.rw=a;G.wins[a]++;G.proj=[];G.fx=[];G.shake=14;ev(G,'ko');G.p.forEach(q=>{q.hide=false;q.ns=false});
 G.banner={txt:'K.O.',sub:'',col:'#ff5c5c',t:0,dur:2};
 G.p[a].win=true;G.p[a].wp=Math.floor(Math.random()*6);
}

