function runner(p,o){return Object.assign({t:'run',o:p.i,x:p.x+p.face*14,dir:p.face,uni:p.ch,age:0,st:0,dT:0,n:1,size:1,sp:250,dmg:50,stun:1,drag:0,dragT:.4,away:false,kind:'special'},o)}
