    if(!f.h1&&f.age>=.8){f.h1=true;if(!V.ko&&Math.abs(V.x-f.x1)<70&&V.y<70){dealHit(G,f.o,V.i,Math.max(1,.25*V.hp),{kind:'special',stun:.9,kb:0});V.vy=300;G.shake=Math.max(G.shake,9)}}
    if(!f.tp&&f.age>=1.15){f.tp=true;P.x=clamp(f.x1-f.dir*36,16,W-16);P.face=f.dir;f.x2=P.x;G.fx.push({t:'ring',x:P.x,age:0,dur:.5,col:'#ff9aff'});if(!V.ko&&Math.abs(V.x-f.x1)<110&&V.y<90){dealHit(G,f.o,V.i,Math.max(1,.56*V.hp),{kind:'special',stun:1.3,kb:f.dir*300});V.vy=320}G.shake=Math.max(G.shake,13);ev(G,'big')}
    if(f.age>=f.dur||P.ko){P.pose='';P.ns=false;P.stun=0;P.sa=0;f.dead=true}
