    if(f.st===1&&f.age>=.55){f.st=2;const d=P.face;f.x1=P.x;P.x=clamp(V.x+d*52,16,W-16);P.cast=null;P.atk={k:'h',t:.04,hitT:.1,dur:.4,hit:true};dealHit(G,f.o,V.i,30,{kind:'skill',stun:1,kb:d*200});G.shake=Math.max(G.shake,6)}
