    if(!f.did&&f.age>=f.hitAt){f.did=true;P.hide=false;P.ns=false;P.x=clamp(V.x,16,W-16);P.pose='upper';P.vy=260;P.stun=Math.max(P.stun,.7);P.face=f.dir;dealHit(G,f.o,V.i,f.dmg,{kind:'special',stun:1.4});V.vy=430;G.shake=Math.max(G.shake,10)}
    if(f.age>=f.dur){P.hide=false;P.ns=false;f.dead=true}
