    if(!f.did&&f.age>=f.hitAt){f.did=true;P.hide=false;P.x=clamp(V.x-P.face*36,16,W-16);P.pose='upper';P.vy=240;P.stun=Math.max(P.stun,.5);dealHit(G,f.o,V.i,f.dmg,{kind:'special',stun:1.4});V.vy=440;G.shake=Math.max(G.shake,10);G.fx.push({t:'ring',x:V.x,age:0,dur:.5,col:'#9ad8ff'})}
    if(f.age>=f.dur){G.p[f.o].hide=false;f.dead=true}
