function step(G,dt,inp){
 G.tick++;
 G.shake=Math.max(0,G.shake-dt*30);G.dim=Math.max(0,G.dim-dt);
 for(const t of G.txt)t.age+=dt;G.txt=G.txt.filter(t=>t.age<.9);
 for(const h of G.hf)h.age+=dt;G.hf=G.hf.filter(h=>h.age<.25);
 if(G.banner){G.banner.t+=dt;if(G.banner.t>G.banner.dur)G.banner=null}
 if(G.phase==='end')return;
 if(G.hsc>0)G.hsc-=dt;
 if(G.hs>0){G.hs-=dt;return}
 if(G.phase==='intro'){
  G.pt+=dt;
  if(G.pt>1.1&&!G.f2){G.f2=true;G.banner={txt:'LUTEM!',sub:'',col:'#fff',t:0,dur:.7}}
  if(G.pt>1.8){G.phase='fight';G.pt=0}
  stepF(G,0,{b:0,p:0},dt);stepF(G,1,{b:0,p:0},dt);return;
 }
 if(G.phase==='fight'){
  G.timer-=dt;
  if(G.timer<=0){
   G.timer=0;const a=G.p[0].hp,b=G.p[1].hp;
   G.phase='ko';G.pt=0;G.proj=[];G.fx=[];G.p.forEach(q=>{q.hide=false;q.ns=false});
   if(a>b){G.rw=0;G.wins[0]++}else if(b>a){G.rw=1;G.wins[1]++}else{G.rw=-1;G.wins[0]++;G.wins[1]++}
   if(G.rw>=0){G.p[G.rw].win=true;G.p[G.rw].wp=Math.floor(Math.random()*6)}
   G.banner={txt:'TEMPO!',sub:'',col:'#ffd84a',t:0,dur:2};ev(G,'ko');
  }
 }
 stepF(G,0,inp[0],dt);stepF(G,1,inp[1],dt);
 if(G.phase==='fight'||G.phase==='ko'){updProj(G,dt);updFx(G,dt)}
 if(G.phase==='ko'){
  G.pt+=dt;
  if(G.pt>2.8){
   if(Math.max(G.wins[0],G.wins[1])>=(G.one?1:2)){
    G.phase='end';G.winner=G.wins[0]>G.wins[1]?0:G.wins[1]>G.wins[0]?1:-1;
   }else{G.round++;resetRound(G)}
  }
 }
}

/* ============ IA ============ */
function aiBits(G,i,ai,dt){
 const p=G.p[i],e=G.p[1-i];ai.cool-=dt;
 if(G.phase!=='fight')return{b:0,p:0};
 const d=Math.abs(e.x-p.x),dir=e.x>p.x?1:-1,toward=dir>0?BR:BL,away=dir>0?BL:BR;
 let pr=0;
 for(const f of G.fx){
  if((f.t==='veh'||(f.t==='run'&&f.st===0))&&f.o!==i&&!f.did){const fd=(p.x-f.x)*f.dir;if(fd>0&&fd<130&&p.y===0&&Math.random()<.12)pr|=BU}
 }
 if(ai.cool<=0){
  ai.cool=rnd(.12,.32);let b=0;
  const ranged=p.ch==='kbene',want=ranged?150:40;
  if(e.atk&&d<85&&Math.random()<.45){b|=BK;ai.cool=rnd(.3,.55)}
  else if(d>want+22)b|=toward;
  else if(ranged&&d<want-40)b|=away;
  const inR=d<=(ranged?260:(62)),r=Math.random();
  if(p.en>=100&&!(p.ch==='reymond'&&p.tf>0))pr|=(p.secOn?BX:BS);
  else if(p.cd<=0&&r<.18&&(!CH[p.ch].sk.close||d<=CH[p.ch].sk.close-15))pr|=BC;
  else if(inR&&r<.58)pr|=BA;else if(inR&&r<.72)pr|=BB;else if(r>.96)pr|=BU;
  ai.b=b;
 }
 return{b:ai.b,p:pr};
}

/* ============ SPRITES (sprite sheets PNG) ============ */
// Recortes dos quadros e ponto dos pés de cada um (medidos nas folhas, ver sprites/rects.json).
