 if(p.secOn&&!palOv){
  c2.fillStyle=pal.aura;c2.globalAlpha=.35;
  for(let k=-2;k<=2;k++){const h=34+Math.sin(t*9+k*1.7)*9;c2.fillRect(k*5-2,-h-14,5,h+14)}
  c2.globalAlpha=1;
 }
 const stance=!p.ko&&!air&&!sit;
