 let fa=.12,ba=-.1,fl=swing,bl=-swing,lunge=0;
 const bob=Math.sin(t*6+(p.i||0))*.07;let up=0;
 if(stn&&!sit)up=-.13;else if(stance)up=.2+bob;
 if(stance){fl=-.3+swing;bl=.3-swing;if(!stn){fa=-1.15+bob;ba=-.75-bob}}
 if(air){fl=.7;bl=-.5;fa=-.9;ba=-.6}
 if(a&&!p.ko){
  const ext=a.t<a.hitT?(-.3+1.3*a.t/a.hitT):Math.max(0,1-(a.t-a.hitT)/(a.dur-a.hitT));
  if(a.k==='h'&&p.ch!=='kbene'){fl=-ext*1.45;fa=-.4;ba=-.9;lean=-ext*.08}else{fa=-.2-ext*1.35;ba=-.7}
  lunge=ext*3;
 }
 if(p.blk){fa=-2;ba=-2.3}
 if(p.cast&&!p.ko&&p.pose!=='sit'){fa=-2.8;ba=-2.6}
 if(p.pose==='held'||p.pose==='held2'){fa=-2.4;ba=-2.6}
 if(p.pose==='self'){fa=-2.6+Math.sin(t*30)*.3}
 if(p.ko){fa=-1.2;ba=-2}
