 if(c.strT==='jk'){R(-tw/2,hip+12,tw,3,pal.str);R(-tw/2,hip+13,tw,1,pal.str2);R(-tw/2,hip+2,ww,2,pal.str)}
 if(c.strT==='cov'){R(-tw/2,hip+19,5,3,pal.str);R(tw/2-5,hip+19,5,3,pal.str);R(-tw/2,hip+4,ww,1,shd(pal.lo))}
 if(pal.camo){for(let k=0;k<16;k++){R(((k*37)%14-7)*bw,hip+((k*53)%20),3,2,k%2?'#2c4224':'#7a8a4a')}}
 if(pal.lan){R(1,hip+6,2,16,pal.lan);R(0,hip+3,5,6,'#f3f3f3');R(1,hip+4,3,2,'#6a7a9a')}
 if(pal.flag)R(-tw/2-1,hip+12,3,3,'#2a9a4a');
 // cabeça
