 if(c.beard){R(-5,hip+22,11,6,'#2a1f1a');R(1,hip+24,4,1,'#8a4a3a')}else if(c.goat){R(1,hip+22,4,4,pal.hair)}
 if(pal.hairT==='bleach')R(-6,hip+30,13,6,pal.hair);
 else if(pal.hairT==='fade'){R(-5,hip+32,11,3,pal.hair)}
 else{R(-5,hip+31,11,4,pal.hair);R(-6,hip+28,2,7,pal.hair)}
 if(pal.sun){R(0,hip+27,8,3,'#0c0c0c');R(5,hip+29,2,1,'#6a8aaa')}
 else if(pal.glasses){R(0,hip+26,8,5,'#222');R(1,hip+27,3,3,'#cfe3ee');R(5,hip+27,2,3,'#cfe3ee')}
 else{R(3,hip+28,2,2,'#111');R(2,hip+30,4,1,pal.hair)}
