 if(p.burn>0&&!p.ko){for(let k=0;k<4;k++){const h=8+Math.sin(t*17+k*2.3)*4;R(-7+k*4,hip+22,3,h,p.burnCol);R(-6+k*4,hip+22,1,h-3,'#fff0a0')}}
 if(p.flash>0){c2.globalAlpha=.55;R(-8,0,16,hip+35,'#ffffff');c2.globalAlpha=1}
 if(p.pose==='zap'){c2.fillStyle='#ffe84a';for(let k=0;k<6;k++){c2.fillRect(rndT(t,k,16)-8,-rndT(t,k+9,60),2,5)}}
 if(p.stun>.6&&!p.ko){for(let k=0;k<3;k++){const an=t*6+k*2.1;c2.fillStyle='#ffe84a';c2.fillRect(Math.cos(an)*8-1,-(hip+42)+Math.sin(an)*2,3,3)}}
