  const fp=fake(f.uni==='girl'?'girl':(CH[uni]?uni:'friend'),f.x-f.dir*k*(f.size>1?0:13),face,{walk:t*2+k,st:f.st===1?'idle':'walk'});
  if(f.st===1&&f.kind==='skill')fp.atk={k:'l',t:.1,hitT:.1,dur:.3};
  drawFighter(c2,fp,t,GY,f.size,friendPal(uni,k));
