/* botões do toque: estado visual */
function padState(){
 if(!G||!$('pad').classList.contains('on'))return;
 const me=G.p[mode==='champ'?Math.max(0,C.side):(mode==='guest'?1:0)],c=CH[me.ch];
 $('bC').classList.toggle('cd',me.cd>0);
 $('bS').classList.toggle('ready',me.en>=100);
 $('bX').classList.toggle('ready',me.en>=100&&me.secOn);
 $('bX').classList.toggle('secr',me.en>=100&&me.secOn);
 $('bX').classList.toggle('cd',!(me.en>=100&&me.secOn));
 $('bE').classList.toggle('ready',!!me.rc);
}

/* ============ REDE (WebRTC manual) ============ */
const Net={pc:null,dc:null,open:false,role:null,
 send(o){if(this.dc&&this.dc.readyState==='open'){try{this.dc.send(JSON.stringify(o))}catch(e){}}},
 close(){try{this.dc&&this.dc.close()}catch(e){}try{this.pc&&this.pc.close()}catch(e){}this.dc=null;this.pc=null;this.open=false;this.role=null}};
const RTC_CFG={iceServers:[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun1.l.google.com:19302'},{urls:['turn:openrelay.metered.ca:80','turn:openrelay.metered.ca:443','turn:openrelay.metered.ca:443?transport=tcp'],username:'openrelayproject',credential:'openrelayproject'}]};
function b64e(u8){let s='';for(let i=0;i<u8.length;i+=0x8000)s+=String.fromCharCode.apply(null,u8.subarray(i,i+0x8000));return btoa(s)}
function b64d(s){const b=atob(s),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u}
async function pack(desc){
 const j=JSON.stringify({t:desc.type,s:desc.sdp});let u=new TextEncoder().encode(j),pre='R';
 if(window.CompressionStream){const cs=new CompressionStream('deflate-raw'),w=cs.writable.getWriter();w.write(u);w.close();u=new Uint8Array(await new Response(cs.readable).arrayBuffer());pre='Z'}
 return 'BF1'+pre+b64e(u);
}
async function unpack(code){
 code=code.replace(/\s+/g,'');if(!code.startsWith('BF1'))throw new Error('Código inválido');
 const pre=code[3];let u=b64d(code.slice(4));
 if(pre==='Z'){const ds=new DecompressionStream('deflate-raw'),w=ds.writable.getWriter();w.write(u);w.close();u=new Uint8Array(await new Response(ds.readable).arrayBuffer())}
 const o=JSON.parse(new TextDecoder().decode(u));return{type:o.t,sdp:o.s};
}
function gather(pc){
 return new Promise(res=>{
  if(pc.iceGatheringState==='complete')return res();
  const to=setTimeout(res,3500);
  pc.addEventListener('icegatheringstatechange',()=>{if(pc.iceGatheringState==='complete'){clearTimeout(to);res()}});
 });
}
function setStatus(s,cls){const e=$('o-status');e.textContent=s;e.className='status'+(cls?' '+cls:'')}
function setupDC(dc){
 Net.dc=dc;
 dc.onopen=()=>{Net.open=true;setStatus('Conectado!','ok');toast('Conectado!');startSelect(Net.role)};
 dc.onclose=()=>{if(Net.open){Net.open=false;if(running||$('s-select').classList.contains('on')){toast('O amigo desconectou.');show('s-menu')}}};
 dc.onmessage=e=>{let m;try{m=JSON.parse(e.data)}catch(_){return}onNet(m)};
}
function onNet(m){
 if(m.k==='sel'){sel.peer=m.ch;sel.peerReady=m.ready;if($('s-select').classList.contains('on')){updSelUI();hostTryStart()}}
 else if(m.k==='start'&&mode==='guest'){startMatch(m.chars)}
 else if(m.k==='back'){startSelect(mode)}
 else if(m.k==='in'&&mode==='host'){remote.b=m.b;remote.p|=m.p}
 else if(m.k==='st'&&mode==='guest'){G=m.s;playEv(G)}
}
const remote={b:0,p:0};
function rtcOK(){return typeof RTCPeerConnection!=='undefined'}
function newPC(role){
 Net.close();Net.role=role;
 const pc=new RTCPeerConnection(RTC_CFG);Net.pc=pc;
 pc.onconnectionstatechange=()=>{if(pc.connectionState==='failed')setStatus('A conexão falhou. Tente de novo; se continuar, use o modo manual ou outra rede.','err')};
 return pc;
}
$('o-host').onclick=async()=>{
 if(!rtcOK()){setStatus('Este navegador ou página não permite conexão direta. Abra o jogo pelo arquivo .html no Chrome do celular.','err');return}
 $('o-hostbox').hidden=false;$('o-joinbox').hidden=true;$('h-offer').value='';setStatus('Gerando código...');
 try{
  const pc=newPC('host');setupDC(pc.createDataChannel('g'));
  await pc.setLocalDescription(await pc.createOffer());await gather(pc);
  $('h-offer').value=await pack(pc.localDescription);setStatus('Código pronto. Envie para o amigo e cole a resposta dele abaixo.');
 }catch(e){setStatus('Erro: '+e.message,'err')}
};
$('h-go').onclick=async()=>{
 try{setStatus('Conectando...');await Net.pc.setRemoteDescription(await unpack($('h-ans').value))}catch(e){setStatus('Resposta inválida: '+e.message,'err')}
};
$('o-join').onclick=()=>{
 if(!rtcOK()){setStatus('Este navegador ou página não permite conexão direta. Abra o jogo pelo arquivo .html no Chrome do celular.','err');return}
 $('o-joinbox').hidden=false;$('o-hostbox').hidden=true;setStatus('');
};
